sp_widget.client_script:
function($rootScope,$scope,spModal,spUtil) {
	/* widget controller */
	var c = this;
	// Use a position indicator to know which record to update
	c.ReviewPos = 0;

	c.selectItem = function(idx) {  
		// Set the position indicator to the index value passed in on select
		c.ReviewPos = idx;
		var id = c.data.reviews[idx].sys_id;
		$rootScope.reviewID = id;
		$rootScope.reviewTable = 'x_snc_createnotes_note';
		$rootScope.$emit('selectReview', id);
	}
	// Subscribe to event.  Set the new title and note values on the 
	// c.data object
	$rootScope.$on('updateTitle', function(event,data) { 
		c.data.reviews[c.ReviewPos].job_title = data.job_title;
	});

	$rootScope.$on('deleteNote', function(event,data) {
		c.data.notes.splice(c.ReviewPos, 1);
	});

	// Record removed from data object on the client and passed to server
	c.snNoteUpdate = function(obj,sysID){

		for (var i=0;i<c.data.notes.length;i++){
			if(c.data.reviews[i].sys_id == obj.data.sys_id){
				if(obj.data.record.review_state){
					c.data.reviews[i].review_state = obj.data.record.review_state.display_value;
				}
				c.server.update();

			}
		}
	}

	spUtil.recordWatch($scope, "x_snc_createnotes_note", "numberANYTHING", function(r) {
//		spUtil.addInfoMessage(JSON.stringify((r.data)));
		c.server.refresh();
		/*
		if(r.data.operation == "insert"){
			c.server.refresh();
		}

		// Calls a Client Script function to do the update and pass the updated data object
		// to the server.
		if(r.data.operation == "update"){
			c.snNoteUpdate(r, r.data.sys_id);
		}


		// Calls a Client Script function which deletes a record on the server and passes
		// the updated data object back to the client.
		if(r.data.operation == "delete"){
			c.snNoteDelete(r.data.sys_id);
		}
		*/
	});


}

sp_widget.css:
h3.panel-title {
  font-size:20px;
  padding-top:5px;
}

.panel {
  box-shadow: 0 0 1rem #6f6363;
}

$secondary-color: #000000;
//==Backgrounds
$background-primary: #ffffff; //--now-color_background--primary
$background-secondary: #f8f6f6; //--now-color_background--secondary
$background-tertiary: #F5F0F1; //--now-color_background--tertiary

//==borders
$border-primary: #8790A1; //--now-color_border--primary
$border-secondary: #BEACB2; //--now-color_border--secondary
$border-tertiary: #E2DADD; //--now-color_border--tertiary

$brand-primary: #c31a1f; //--now-color--primary-1
$brand-danger: #E42338; //--now-color_alert--critical-2
$brand-warning: #F0E000; //--now-color_alert--warning-2
$brand-moderate: #8B6BFF; //--now-color_alert--moderate-2 NEW
$brand-low: #9698A4; //--now-color_alert--low-2 NEW
$brand-success: #51ae00; //--now-color_alert--positive-2
$brand-info: #38aaf4; //--now-color_alert--info-2

.draft {
  color:#6B7280 !important;
}

.inprogress {
  color:#F59E0B !important;
}

.onhold {
  color:#EF4444 !important;
}

.validated {
  color:#5cb85c !important;
}

.completed {
  color:#c31a1f !important;
}

.incompleted {
  color:#181B20 !important;
}


.card{
  border-radius: 10px;
  padding: 10px 10px 10px 20px;
  box-shadow: 0 0 0rem 1px #ddd;
  margin: 0px 15px 10px 15px;
  border-right: 0.5rem solid $brand-primary;

  &:hover{
    background-color: rgb(231,229,229) !important;
    //box-shadow: 0 0 1rem #a29393;
  }
}

.tag{  
  background-color: $brand-color;
  color: #ffffff;
  padding: 2px 8px;
  border-radius: 10px;
}

.avatar-container {
  margin-right:5px;
}

.avatar-display {
  display: flex;
  align-items: center;
}

.heading{
  margin-top: 1.1rem;
  margin-bottom: 1.1rem;
  color:$text-color;
}

.description{
  color: $text-muted;
}

.button{
  color: #ffffff;
  background-color: #ffffff;
  padding: 0.5em 1em;
  border-radius: 6px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  border: 2px solid $secondary-color;
  box-shadow: inset 0 0 0 0 #ffffff;
  transition: ease-out 0.4s;
  cursor: pointer;

  &:hover{
    background-color: #ffffff !important;
    color: #000000;
    box-shadow: inset 400px 0 0 0 #ffffff;
  }
}
.w-100{
  width: 100%;
}

.bg{
  height: 20rem;
  background: #ffffff;
  border-radius: 10px;
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
}

.position-absolute{
  position: absolute;
}

.form-group {
  margin-bottom:.25rem;
}

.layout {
	display:flex;
  flex-direction: row;
	padding-left: 30px;
  padding-right: 20px;
}

/*********************************** radio butt0n ***********************************/
*,
*:after,
*:before {
  box-sizing: border-box;
}

$primary-color: #00005c; // Change color here. C'mon, try it! 
$text-color: mix(#000, $brand-primary, 64%);

body {
  color: $text-color;
  font-size: calc(1em + 1.25vw);
  background-color: mix(#fff, $brand-primary, 90%);
  min-height: 100vh;
}

.main {
  flex: 1 0 auto;
  min-height: calc(-515.49px + 100vh);
}

.sp-form-container {
  margin-bottom : 1em;
}

.radio {
  display: flex;
  flex-direction: row;
  margin-top: 5px;
  margin-bottom: 5px;
  width: 100%;
  justify-content: flex-end;
}

.radio label {
  display: flex;
  cursor: pointer;
  font-weight: 500;
  position: relative;
  overflow: hidden;
  margin-bottom: 0.175em;
  /* Accessible outline */
  /* Remove comment to use */ 
  /*
  &:focus-within {
  outline: .125em solid $primary-color;
}
  */

  input[type="radio"] {
    position: absolute;
    left: -9999px;
    &:checked + span {
      background-color: mix(#fff, $brand-primary, 84%);
      &:before {
        box-shadow: inset 0 0 0 0.4375em $brand-primary;
      }
    }
  }

  span {
    display: flex;
    align-items: center;
    padding: 0.375em 0.75em 0.375em 0.375em;
    border-radius: 99em; // or something higher...
    transition: 0.25s ease;
    &:hover {
      background-color: mix(#fff, $brand-primary, 84%);
    }
    &:before {
      display: flex;
      flex-shrink: 0;
      content: "";
      background-color: #fff;
      width: 1.25em;
      height: 1.25em;
      border-radius: 50%;
      margin-right: 0.375em;
      transition: 0.25s ease;
      box-shadow: inset 0 0 0 0.125em $brand-primary;
    }
  }
}

h4, .h4, h5, .h5, h6, .h6 {
  margin-top: 1.1rem;
  margin-bottom: 1.1rem;
}

h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: "Lato", sans-serif;
  font-weight: 600;
  line-height: 1.1;
  color: inherit;
}

/*********************************** input ***********************************/
:root {
  --input-focus-h: 245;
  --input-focus-s: 100%;
  --input-focus-l: 42%;
}

.input {
  width:100%;
  font-size: 14px;
  // Capitalized to prevent Sass
  // thinking it's the Sass max()
  font-size: Max(14px, 1em);
  font-family: inherit;
  padding: 0.25em 0.5em;
  background-color: #fff;
  border: 1px solid $brand-primary;
  border-top: none;
  border-left: none;
  border-right: none;
  border-radius: 4px;
  transition: 180ms box-shadow ease-in-out;
}

.input:focus {
  border-color: hsl(
    var(--input-focus-h),
    var(--input-focus-s),
    var(--input-focus-l)
  );
  /*
  box-shadow: 0 0 0 1px
    hsla(
      var(--input-focus-h),
      var(--input-focus-s),
      calc(var(--input-focus-l) + 40%),
      0.8
    );
  */
}

.input:not(textarea) {
  line-height: 1;
  height: 2.25rem;
}

[id^="textarea_ea_"] {
  margin-bottom:15px;
}

input[type="file"] {
  font-size: 0.9em;
  padding-top: 0.35rem;
}

textarea.input {
  resize: vertical;
}

.input[readonly] {
  border-style: dotted;
  cursor: not-allowed;
  color: #777;
}

.input[disabled] {
  --input-border: #ccc;

  background-color: #eee;
  cursor: not-allowed;
}

label {
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
}

.input + label {
  margin-top: 2rem;
}

sp_widget.script:
(function() {

	/************************************* Collaborator Satisfaction ************************************/
	data.collaborator_work_environment = getOptionItems("collaborator_work_environment");
	data.collaborator_workload = getOptionItems("collaborator_workload");
	data.collaborator_work_atmosphere_climate = getOptionItems("collaborator_work_atmosphere_climate");
	data.collaborator_team_spirit = getOptionItems("collaborator_team_spirit");
	data.collaborator_relationship_manager = getOptionItems("collaborator_relationship_manager");
	data.collaborator_general_motivation = getOptionItems("collaborator_general_motivation");

	/**************************************** Manager Satisfaction **************************************/
	data.manager_effectiveness_and_efficiency = getOptionItems("manager_effectiveness_and_efficiency");
	data.manager_customer_satisfaction = getOptionItems("manager_customer_satisfaction");
	data.manager_cooperation_helpfulness = getOptionItems("manager_cooperation_helpfulness");
	data.manager_identification_institution = getOptionItems("manager_identification_institution");
	data.manager_vision = getOptionItems("manager_vision");
	data.manager_solution_oriented_proactive = getOptionItems("manager_solution_oriented_proactive");
	data.manager_leadership_na = getOptionItems("manager_leadership_na");
	data.other_manager_evaluation_2 = getOptionItems("other_manager_evaluation_2");
	data.other_manager_evaluation_1 = getOptionItems("other_manager_evaluation_1");
	data.objective_measure = getOptionItems("review_objective_or_meausre");
	data.training_and_professional_development = getOptionItems("training_and_professional_development");
	data.remarks_comments = getOptionItems("remarks_comments");
	data.collaborator_satisfaction = getOptionItems("collaborator_satisfaction");
	data.manager_evaluation = getOptionItems("manager_evaluation");

	function getOptionItems(field) {
		var inData = [];
		var language = gs.getSession().getLanguage();
		var choices = GlideChoiceList.getChoiceList("x_snc_createnotes_note", field);
		var obj={};
		var grForLabels = new GlideRecord("x_snc_createnotes_note");

		inData.push(grForLabels.getElement(field).getLabelLang(language));

		for (i = 0; i < choices.getSize(); i++){
			obj.value = choices.getChoice(i).getValue();
			obj.label = choices.getChoice(i).getLabel();
			inData.push(obj);
			obj={};
		}
		return inData;
	}
	/****************************************************************************************************/

	data.reviews = [];
	var collabReviewGR = new GlideRecord('x_snc_createnotes_note');
	collabReviewGR.orderByDesc('sys_created_on');
	//collabReviewGR.setLimit(options.maximum_records_to_display);
	collabReviewGR.query();
	while (collabReviewGR.next()) {
		var CollabReviewObj = {};

		$sp.getRecordDisplayValues(CollabReviewObj, collabReviewGR, 'collaborator,review_date,job_title, job_department, review_date ,sys_id');
		CollabReviewObj.image=getAvatarPath(collabReviewGR.getValue(("collaborator")));
		CollabReviewObj.borderright = collabReviewGR.getValue("review_state");
		data.reviews.push(CollabReviewObj);
	}
	console.log(data.reviews);

	if (input) {
		if (input.action == 'newNote') {
			var newNote = new GlideRecord('x_snc_createnotes_note');
			newNote.newRecord();
			var id = newNote.insert();
			data.noteID = id;
			data.newNote = {};
			$sp.getRecordValues(data.newNote,newNote,"title,note,sys_id");
		}
		if (input.action == 'snDeleteNote') {
			var delNote = new GlideRecord('x_snc_createnotes_note');
			// The notes record should already be gone.  Just
			// making sure it no longer exists.
			if(delNote.get(input.noteID)){
				delNote.deleteRecord();
			}

		}
	}

	function getAvatarPath(userID) {
		var avatarPath = '';
		var grUser = new GlideRecord("sys_user");
		grUser.addEncodedQuery("sys_id=" + userID );
		grUser.setLimit(1);
		grUser.query();
		if (grUser.hasNext()) {
			grUser.next();
			var avatarRec = GlideAvatarFinder.getAvatarPath(grUser.getValue("sys_id")); // pass sys_id of user
			avatarPath = (avatarRec != null && avatarRec) ? encodeURI(avatarRec.toString().replace("?t=small", "")) : '';
		}

		return avatarPath;
	}

}
)();
